// Round p (pointer or byte index) up to a correctly-aligned value for all
// data types (int, long, ...).   The result is unsigned int and must be
// cast to any desired pointer type.

// Definitions related to sockets: types, address families, options.

// Data types.
type Gid_t = uint32 /* socket.h:87:25 */

type Off_t = int64 /* socket.h:92:25 */

type Pid_t = int32 /* socket.h:97:25 */

type Sa_family_t = uint8 /* socket.h:103:20 */

type Socklen_t = uint32 /* socket.h:108:28 */

// XXX Not explicitly defined by POSIX, but function return types are
type Ssize_t = int64 /* socket.h:120:26 */

// [XSI] The iovec structure shall be defined as described in <sys/uio.h>.
type Iovec = struct {
	Fiov_base uintptr
	Fiov_len  uint64
} /* socket.h:128:1 */

// Types

// Option flags per-socket.
//  (ATOMIC proto)

// Additional options, not kept in so_options.
//efine	SO_PRIVSTATE	0x1009		   get/deny privileged state

// Structure used for manipulating linger option.
type Linger = struct {
	Fl_onoff  int32
	Fl_linger int32
} /* socket.h:210:1 */

// Level number for (get/set)sockopt() to apply to socket itself.

// Address families.
//define pseudo_AF_BLUE	26	   Identify packets for Blue Box - Not used

// [XSI] Structure used by kernel to store most addresses.
type Sockaddr = struct {
	Fsa_len    uint8
	Fsa_family uint8
	Fsa_data   [14]int8
} /* socket.h:294:1 */

// Structure used by kernel to pass protocol
// information in raw sockets.
type Sockproto = struct {
	Fsp_family   uint16
	Fsp_protocol uint16
} /* socket.h:307:1 */

// RFC 2553: protocol-independent placeholder for socket addresses

// [XSI] sockaddr_storage
type Sockaddr_storage = struct {
	Fss_len     uint8
	Fss_family  uint8
	F__ss_pad1  [6]int8
	F__ss_align int64
	F__ss_pad2  [112]int8
} /* socket.h:327:1 */

// Protocol families, same as address families for now.

// These do not have socket-layer support:

// Definitions for network related sysctl, CTL_NET.
//
// Second level is protocol family.
// Third level is protocol number.
//
// Further levels are defined by the individual families below.

// PF_ROUTE - Routing table
//
// Three additional levels are defined:
//	Fourth: address family, 0 is wildcard
//	Fifth: type of info, defined below
//	Sixth: flag(s) to mask with for NET_RT_FLAGS

// Maximum queue length specifiable by listen.

// [XSI] Message header for recvmsg and sendmsg calls.
// Used value-result for recvmsg, value only for sendmsg.
type Msghdr = struct {
	Fmsg_name       uintptr
	Fmsg_namelen    uint32
	F__ccgo_pad1    [4]byte
	Fmsg_iov        uintptr
	Fmsg_iovlen     int32
	F__ccgo_pad2    [4]byte
	Fmsg_control    uintptr
	Fmsg_controllen uint32
	Fmsg_flags      int32
} /* socket.h:434:1 */

// Header for ancillary data objects in msg_control buffer.
// Used for additional information with/about a datagram
// not expressible by flags.  The format is a sequence
// of message elements headed by cmsghdr structures.
type Cmsghdr = struct {
	Fcmsg_len   uint32
	Fcmsg_level int32
	Fcmsg_type  int32
} /* socket.h:472:1 */

// given pointer to struct cmsghdr, return pointer to data

// given pointer to struct cmsghdr, return pointer to next cmsghdr

// RFC 2292 additions

// "Socket"-level control message types:

// howto arguments for shutdown(2), specified by Posix.1g.

// sendfile(2) header/trailer struct
type Sf_hdtr = struct {
	Fheaders     uintptr
	Fhdr_cnt     int32
	F__ccgo_pad1 [4]byte
	Ftrailers    uintptr
	Ftrl_cnt     int32
	F__ccgo_pad2 [4]byte
} /* socket.h:546:1 */

